  'A secret URL that redeploys this service when called with POST — from a CI job, a cron or a script, without a Git webhook. It deploys as you, with your access checked on every call. Treat the URL like a password.':
    'POST ile çağrıldığında bu servisi yeniden dağıtan gizli bir URL — Git webhook’u olmadan bir CI işinden, cron’dan ya da betikten. Sizin adınıza dağıtır ve her çağrıda erişiminiz kontrol edilir. URL’yi bir parola gibi saklayın.',
