  'Abort this canary?': 'Bu canary iptal edilsin mi?',
  'Abort': 'İptal et',
  'After the new container passes its healthcheck, it gets a growing share of the requests, step by step, and all of them after the last step. A step that fails sends every request back to the previous release and fails the deploy. Available for eligible Docker services with a domain. First deploys and rollbacks switch all traffic at once; Swarm deploys use their native rolling update.':
    'Yeni konteyner sağlık kontrolünü geçtikten sonra isteklerin adım adım artan bir payını, son adımdan sonra da tamamını alır. Başarısız olan bir adım tüm istekleri önceki sürüme geri gönderir ve dağıtımı başarısız sayar. Alan adı olan uygun Docker servislerinde kullanılabilir. İlk dağıtımlar ve geri almalar tüm trafiği tek seferde geçirir; Swarm dağıtımları kendi kademeli güncellemesini kullanır.',
