  'Every 30 minutes the registry is probed; when this image\'s tag moved, a normal deployment is queued through the usual health checks on its node. Enabling only sets a baseline — it never deploys by itself.':
    'Kayıt deposu her 30 dakikada bir yoklanır; bu imajın etiketi değiştiyse, düğümünde olağan sağlık kontrollerinden geçen normal bir dağıtım kuyruğa alınır. Açmak yalnızca bir başlangıç noktası belirler — kendi başına asla dağıtım yapmaz.',
  'Every 30 minutes the registry is probed; when this image\'s tag moved, a normal deployment is queued through the usual health checks. Enabling only sets a baseline — it never deploys by itself.':
    'Kayıt deposu her 30 dakikada bir yoklanır; bu imajın etiketi değiştiyse, olağan sağlık kontrollerinden geçen normal bir dağıtım kuyruğa alınır. Açmak yalnızca bir başlangıç noktası belirler — kendi başına asla dağıtım yapmaz.',
  'Auto-update': 'Otomatik güncelleme',
  'Container port (Traefik target)': 'Konteyner portu (Traefik hedefi)',
  'Healthcheck timeout (seconds)': 'Sağlık kontrolü zaman aşımı (saniye)',
  'How long a deploy waits for the new container to answer, 10–3600. Blank = 300.':
    'Bir dağıtımın yeni konteynerin yanıt vermesini ne kadar bekleyeceği, 10–3600. Boş = 300.',
  'Healthcheck': 'Sağlık kontrolü',
  'Container running: the deploy only waits for the container to stay up 10 s, for services with no HTTP or TCP port (UDP game servers, VoIP, workers).':
    'Konteyner çalışıyor: dağıtım yalnızca konteynerin 10 sn ayakta kalmasını bekler; HTTP ya da TCP portu olmayan servisler için (UDP oyun sunucuları, VoIP, worker’lar).',
  'Default healthcheck (legacy behaviour)': 'Varsayılan sağlık kontrolü (eski davranış)',
  'HTTP readiness (2xx / 3xx response)': 'HTTP hazırlığı (2xx / 3xx yanıtı)',
  'TCP readiness (port accepts connections)': 'TCP hazırlığı (port bağlantı kabul ediyor)',
  'Container running (no port probe)': 'Konteyner çalışıyor (port yoklaması yok)',
  'Command inside the container': 'Konteyner içinde komut',
  'Docker labels': 'Docker etiketleri',
  'Not a label: {labels} (key=value; ninedeploy.*, com.docker.* and traefik.* are reserved)':
    'Etiket değil: {labels} (key=value; ninedeploy.*, com.docker.* ve traefik.* ayrılmıştır)',
  'key=value per line, for tools on the host that read container labels. Routing is not affected. Applies on the next deploy.':
    'Her satıra bir key=value; sunucuda konteyner etiketlerini okuyan araçlar için. Yönlendirme etkilenmez. Sonraki dağıtımda uygulanır.',
  'Healthcheck command': 'Sağlık kontrolü komutu',
  'Runs as the container\'s Docker healthcheck (sh -c, every 5 s); the deploy waits until it reports healthy. Needs node agent 0.16.4+ and a shell in the image.':
    'Konteynerin Docker sağlık kontrolü olarak çalışır (sh -c, 5 sn’de bir); dağıtım sağlıklı bildirene kadar bekler. Düğüm ajanı 0.16.4+ ve imajda bir kabuk gerekir.',
  'Run with sh -c inside the container until it exits 0, e.g. pg_isready -U app or curl -fsS localhost:3000/up. The image needs a shell.':
    'Konteyner içinde sh -c ile 0 koduyla çıkana kadar çalıştırılır, örn. pg_isready -U app ya da curl -fsS localhost:3000/up. İmajda bir kabuk gerekir.',
  'Volume mount': 'Birim bağlama noktası',
  'Build configuration': 'Derleme yapılandırması',
  'static (admin only — runs on the host)': 'static (yalnızca yönetici — sunucuda çalışır)',
  'Output directory': 'Çıktı dizini',
