  'Port Mappings (TCP / UDP)': 'Port eşlemeleri (TCP / UDP)',
  'Mapping': 'Eşleme',
  'Publish extra host ports straight to the container, outside Traefik: game servers, VoIP/RTP, DNS, VPNs. A range such as {range} maps onto the same number of container ports starting at the container port (empty = the same ports). A single TCP port can take an allow list: only those addresses get in, which a host firewall cannot enforce on Docker ports. Leave the IP empty to listen on every address of the host, or enter one of its IPs to dedicate that address. At most {max} ports in total; the next deploy applies the change, stopping the old container first.':
    'Ek sunucu portlarını Traefik dışından doğrudan konteynere yayınlayın: oyun sunucuları, VoIP/RTP, DNS, VPN’ler. {range} gibi bir aralık, konteyner portundan başlayarak aynı sayıda konteyner portuna eşlenir (boş = aynı portlar). Tek bir TCP portu izin listesi alabilir: yalnızca bu adresler girebilir; bunu bir sunucu güvenlik duvarı Docker portlarında uygulayamaz. Sunucunun tüm adreslerinde dinlemek için IP’yi boş bırakın ya da o adresi ayırmak için IP’lerinden birini girin. Toplamda en fazla {max} port; değişikliği sonraki dağıtım, önce eski konteyneri durdurarak uygular.',
  'This service runs on a node: the ports are published on the node\'s own addresses, and its agent must be v0.16.1 or newer (an older one refuses the deploy and says so).':
    'Bu servis bir düğümde çalışıyor: portlar düğümün kendi adreslerinde yayınlanır ve ajanı v0.16.1 ya da daha yeni olmalıdır (daha eskisi dağıtımı reddeder ve bunu bildirir).',
