  'Save placement': 'Yerleşimi kaydet',
  'A build away from where the service runs hands the image over by a sealed stream through the panel, verified by its digest. With a push registry it is pushed there and pulled on the target instead (a registry credential from Sources). Applied on the next deploy.':
    'Servisin çalıştığı yerden farklı bir yerde yapılan derleme, imajı panel üzerinden mühürlü bir akışla, özetiyle doğrulanarak teslim eder. Gönderim kayıt deposu seçiliyse imaj oraya gönderilir ve hedefte oradan çekilir (Kaynaklar\'daki bir kayıt deposu kimlik bilgisiyle). Sonraki dağıtımda uygulanır.',
  'Repository-backed Docker builds on the panel or a capable node also archive their promotion artifact here. Node-built artifacts retain a verified image copy on the panel. A recorded registry digest can restore the same image after local cleanup; registry retention must keep that digest.':
    'Panelde ya da uygun bir düğümde yapılan depo tabanlı Docker derlemeleri, terfi çıktılarını da burada arşivler. Düğümde derlenen çıktılar panelde doğrulanmış bir imaj kopyası tutar. Kayıtlı bir kayıt deposu özeti, yerel temizlikten sonra aynı imajı geri yükleyebilir; kayıt deposunun saklama ilkesi bu özeti korumalıdır.',
