  'plain containers': 'düz konteynerler',
  'Swarm spreads the replicas over the panel host and the nodes that joined the swarm, behind Traefik. It runs docker services from an image or a repository, with no node pin, volumes, published ports, Docker socket, databases or fan-out targets. Applied on the next deploy.':
    'Swarm, kopyaları Traefik arkasında panel sunucusuna ve swarm\'a katılan düğümlere dağıtır. İmajdan ya da depodan gelen docker servislerini çalıştırır; düğüm sabitleme, birim, yayımlanmış port, Docker soketi, veritabanı ya da çoklu hedef desteklenmez. Sonraki dağıtımda uygulanır.',
  'Only an instance operator can change the orchestrator.': 'Orkestratörü yalnızca bir örnek operatörü değiştirebilir.',
