  'Autoscaling turned off': 'Otomatik ölçekleme kapatıldı',
  'Could not save the autoscaling': 'Otomatik ölçekleme kaydedilemedi',
  'Autoscaling': 'Otomatik ölçekleme',
  'Runs between a minimum and a maximum number of containers, set by load, without a redeploy. Every 30 s it compares the metric per container with the target (within 10 % of it nothing changes), and adds or removes containers once the need has lasted the scale-up or scale-down window.':
    'Yeniden dağıtım gerektirmeden, yüke göre en az ve en çok konteyner sayısı arasında çalışır. Her 30 sn\'de bir konteyner başına metriği hedefle karşılaştırır (hedefin %10\'u içinde hiçbir şey değişmez) ve ihtiyaç ölçek büyütme ya da küçültme penceresi boyunca sürdüğünde konteyner ekler veya kaldırır.',
  'It applies fully at the next deploy, which creates the spare containers; until then it can only scale down. Turned off, the containers serving now keep serving until the next deploy, which runs the Replicas count again.':
    'Yedek konteynerleri oluşturan sonraki dağıtımda tamamen uygulanır; o zamana kadar yalnızca küçültebilir. Kapatıldığında, şu an hizmet veren konteynerler, Kopyalar sayısını yeniden çalıştıran sonraki dağıtıma kadar hizmet vermeye devam eder.',
  'This service runs on a node, so the autoscaler holds for it for now.':
    'Bu servis bir düğümde çalışıyor, bu yüzden otomatik ölçekleyici şimdilik onun için bekliyor.',
  'This service runs on Swarm, which scales with its own replicas; the autoscaler holds for it.':
    'Bu servis, kendi kopyalarıyla ölçeklenen Swarm üzerinde çalışıyor; otomatik ölçekleyici onun için bekliyor.',
  'Min containers': 'En az konteyner',
  'Never fewer, 1–{max}.': 'Asla daha az değil, 1–{max}.',
  'Max containers': 'En çok konteyner',
  'Never more, up to {max}. Each deploy creates this many.':
    'Asla daha fazla değil, en çok {max}. Her dağıtım bu kadar oluşturur.',
  'Metric': 'Metrik',
  'Target': 'Hedef',
  'Requests per second per container.': 'Konteyner başına saniyedeki istek sayısı.',
  'Percent per container, at most 100.': 'Konteyner başına yüzde, en çok 100.',
  '{cpu} is a percentage of the service\'s CPU limit (of one core without one). {memory} is a percentage of its memory limit, so it needs one. {rps} is requests per second over the last minute, and needs traffic analytics (an operator turns it on in {link}); without it, the autoscaler holds and says so.':
    '{cpu}, servisin CPU sınırının yüzdesidir (sınır yoksa bir çekirdeğin). {memory}, bellek sınırının yüzdesidir, bu yüzden bir sınır gerektirir. {rps}, son bir dakikadaki saniye başına istek sayısıdır ve trafik analitiği gerektirir (bir operatör bunu {link} bölümünden açar); bu olmadan otomatik ölçekleyici bekler ve bunu bildirir.',
  'This service has no memory limit, so memory would read the host\'s memory. Set one under Resource limits.':
    'Bu servisin bellek sınırı yok, bu yüzden memory sunucunun belleğini okur. Kaynak sınırları altından bir sınır belirleyin.',
