  'AI assistant': 'Yapay zekâ asistanı',
  'Bring your own key: the panel asks Claude or an OpenAI-compatible endpoint to diagnose failed builds and to read a running service\'s logs. The sanitized tail of the log is sent to the provider — pick a provider you trust. It spends this key\'s budget, so only instance operators and members of a workspace an operator owns can use it.':
    'Kendi anahtarınızı getirin: panel, başarısız derlemeleri teşhis etmesi ve çalışan bir servisin loglarını okuması için Claude\'a veya OpenAI uyumlu bir uç noktaya başvurur. Logun temizlenmiş son kısmı sağlayıcıya gönderilir — güvendiğiniz bir sağlayıcı seçin. Bu anahtarın bütçesini harcar; bu yüzden yalnızca kurulum operatörleri ve bir operatöre ait çalışma alanının üyeleri kullanabilir.',
