  'Allow "{name}" on nodes?': '"{name}" düğümlerde kullanılsın mı?',
  'This long-lived token or deploy key is then sent, sealed, to a node for each clone it runs, and is removed when the clone ends. Anyone with root on that node could read it while the clone runs. Prefer building on the panel host (Service → Settings → Build placement) or a GitHub App, whose tokens are short-lived. A node owner can refuse with NINEDEPLOY_AGENT_STATIC_CREDENTIALS=off.':
    'Bu uzun ömürlü token veya dağıtım anahtarı, bir düğümün çalıştırdığı her klonlama için mühürlenmiş olarak o düğüme gönderilir ve klonlama bitince kaldırılır. O düğümde root yetkisi olan herkes klonlama sürerken onu okuyabilir. Panel sunucusunda derlemeyi (Servis → Ayarlar → Derleme yeri) veya token\'ları kısa ömürlü olan bir GitHub App\'i tercih edin. Bir düğüm sahibi NINEDEPLOY_AGENT_STATIC_CREDENTIALS=off ile reddedebilir.',
  'Stop pinning host keys of "{name}"?': '"{name}" sunucu anahtarlarını sabitlemek bırakılsın mı?',
  'Reset the pinned host keys of "{name}"?': '"{name}" sabitlenmiş sunucu anahtarları sıfırlansın mı?',
  'Stop pinning': 'Sabitlemeyi bırak',
  'Reset keys': 'Anahtarları sıfırla',
  'The next clone accepts whatever the Git host presents and remembers it from then on, and without pinning a changed key goes unnoticed between deploys. Do this when the host really rotated its key. If you did not expect a change, leave the keys as they are: something may be intercepting the connection.':
    'Bir sonraki klonlama Git sunucusunun sunduğu anahtarı kabul eder ve o andan itibaren hatırlar; sabitleme olmadan değişen bir anahtar dağıtımlar arasında fark edilmez. Bunu sunucu anahtarını gerçekten yenilediğinde yapın. Bir değişiklik beklemiyorsanız anahtarları olduğu gibi bırakın: bağlantıyı araya giren bir şey olabilir.',
  'The next clone accepts whatever the Git host presents and remembers it from then on. Do this when the host really rotated its key. If you did not expect a change, leave the keys as they are: something may be intercepting the connection.':
    'Bir sonraki klonlama Git sunucusunun sunduğu anahtarı kabul eder ve o andan itibaren hatırlar. Bunu sunucu anahtarını gerçekten yenilediğinde yapın. Bir değişiklik beklemiyorsanız anahtarları olduğu gibi bırakın: bağlantıyı araya giren bir şey olabilir.',
