  'Extra Traefik routers, services and middlewares, kept in {file} beside the generated routes. Allowed: {http} (routers, middlewares, services, serversTransports), {tcp} (routers, services, middlewares) and {tlsOptions}.':
    'Oluşturulan rotaların yanında {file} içinde tutulan ek Traefik yönlendiricileri, servisleri ve ara katmanları. İzin verilenler: {http} (routers, middlewares, services, serversTransports), {tcp} (routers, services, middlewares) ve {tlsOptions}.',
  'Every name you define must start with {dash} or {underscore}. Routers use the {web} / {websecure} entry points (TCP: {websecure}), stay below the panel router\'s priority, and may only use the {letsencrypt} resolver. Refused: {udp}, {tlsCertificates} / {tlsStores} (upload certificates instead), plugins, file paths (certFile, keyFile, CA files), YAML aliases and merge keys. Node proxies do not receive it.':
    'Tanımladığınız her ad {dash} veya {underscore} ile başlamalıdır. Yönlendiriciler {web} / {websecure} giriş noktalarını kullanır (TCP: {websecure}), panel yönlendiricisinin önceliğinin altında kalır ve yalnızca {letsencrypt} çözümleyicisini kullanabilir. Reddedilenler: {udp}, {tlsCertificates} / {tlsStores} (bunun yerine sertifika yükleyin), eklentiler, dosya yolları (certFile, keyFile, CA dosyaları), YAML takma adları ve birleştirme anahtarları. Düğüm proxy\'leri bunu almaz.',
